    comp(g,'multiply',.8,()=>{g.fillStyle=rg(g,250,-20,340,[[0,'#fff0d8'],[.45,'#d8b890'],[.8,'#6a5a68'],[1,'#2a2638']]);g.fillRect(0,0,320,144)});
